  --btn-focus-outline-color: color-mix(in oklab, var(--btn-color) 55%, transparent);

  &:hover {
    background-color: color-mix(in oklab, var(--btn-color) 16%, transparent);
  }

  &:active {
    background-color: color-mix(in oklab, var(--btn-color) 22%, transparent);
  }
}

@utility btn-ghost {
  color: var(--btn-fg);
  --btn-focus-outline-color: var(--btn-ring-color);

  &:hover {
    background-color: var(--btn-hover-color);
  }

  &:active {
