/*
 * La flèche du select : deux traits en dégradé, donc une couleur que l'on
 * choisit (un SVG en data: garderait la sienne). Réglages :
 *   --ui-select-indicator-color  la couleur (muted-foreground par défaut)
 *   --ui-select-indicator-size   la demi-largeur de la flèche (5px)
 *   --ui-select-indicator-stroke l'épaisseur du trait (1.5px)
 *   --ui-select-indicator-image  une autre image, si l'on veut la sienne
 */
@utility ui-form-select-indicator {
  --_c: var(--ui-select-indicator-color, var(--color-muted-foreground, #6b7280));
  --_s: var(--ui-select-indicator-size, 5px);
  --_w: calc(var(--ui-select-indicator-stroke, 1.5px) / 2);
  background-image: var(--ui-select-indicator-image,
      linear-gradient(45deg, transparent calc(50% - var(--_w)), var(--_c) calc(50% - var(--_w)), var(--_c) calc(50% + var(--_w)), transparent calc(50% + var(--_w))),
      linear-gradient(-45deg, transparent calc(50% - var(--_w)), var(--_c) calc(50% - var(--_w)), var(--_c) calc(50% + var(--_w)), transparent calc(50% + var(--_w))));
  background-position: right calc(0.875rem + var(--_s)) top calc(50% + 1px), right 0.875rem top calc(50% + 1px);
  background-repeat: no-repeat;
  background-size: var(--_s) var(--_s);
  padding-right: 2.5rem;
  print-color-adjust: exact;

  &:disabled {
    --_c: color-mix(in oklab, var(--ui-select-indicator-color, var(--color-muted-foreground, #6b7280)) 50%, transparent);
  }
}

