}

@utility ui-checkbox-radio-base {
  --u-check-radio-color: var(--check-radio-offset-color, currentColor);
  @apply relative appearance-none p-0 [print-color-adjust:exact] inline-block align-middle [background-origin:border-box] [user-select:none] [flex-shrink:0] [--un-shadow:0_0_#0000] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:[outline-color:var(--u-check-radio-color)] focus:ring-0 focus:checked:[background-color:currentColor] checked:hover:[border-color:transparent] [border-color:transparent] [background-color:currentColor] [background-size:100%_100%] [background-position:center] [background-repeat:no-repeat];

  /* Invalide : la bordure, et l'anneau du focus, prennent la couleur d'erreur. */
  &:is([data-invalid], [aria-invalid="true"]):not(:checked, :indeterminate) {
    border-color: var(--ui-checkbox-invalid-color, var(--ui-input-invalid-outline, var(--color-destructive, #dc2626)));
  }

  &:is([data-invalid], [aria-invalid="true"]) {
    --u-check-radio-color: var(--ui-checkbox-invalid-color, var(--ui-input-invalid-outline, var(--color-destructive, #dc2626)));
  }

  /*
   * La marque (coche, tiret, point) est un pseudo-élément : sa couleur vient
   * de --checkbox-mark-color (primary-foreground, sinon blanc), sa forme d'un masque. On
   * peut donc avoir une case blanche et une coche de la couleur du thème.
   */
  &::before {
    content: "";
    position: absolute;
    inset: 0;
    background-color: var(--ui-checkbox-mark-color, var(--checkbox-mark-color, var(--primary-foreground, #fff)));
    mask: var(--_mark, none) center / 100% 100% no-repeat;
    opacity: 0;
    scale: .6;
    transition: opacity .12s ease, scale .12s ease;
    pointer-events: none;
  }

  /* Le point du radio : un cercle plein, sa taille réglable avec --radio-dot-size (37.5 %). */
  &[type="radio"]::before {
    inset: calc((100% - var(--radio-dot-size, 37.5%)) / 2);
    border-radius: 9999px;
    mask: none;
  }

  &:checked::before,
  &:indeterminate::before {
    opacity: 1;
    scale: 1;
  }

  @media (forced-colors: active) {
    &::before {
      background-color: CanvasText;
    }
  }
}



