/*
  Animation des panneaux flottants (dropdown, popover, tooltip, listbox,
  autocomplete) : data-state="open" vient de Flexilla, data-show-placement
  (top, bottom-start, right…) de flexipop.

  Entrée : fondu, léger agrandissement et glissement depuis le déclencheur,
  sur une courbe douce. Sortie : plus courte ; la visibilité ne se coupe qu'à
  la fin, pour que la fermeture soit animée aussi. Ouvert, le panneau finit
  sans transform : il ne devient pas le repère des éléments fixed qu'il
  contient.
*/
@utility fx-popper-motion {
  --fx-motion-distance: 0.375rem;
  --fx-motion-x: 0px;
  --fx-motion-y: calc(var(--fx-motion-distance) * -1);
  transform-origin: var(--fx-motion-origin, top center);
  opacity: 0;
  visibility: hidden;
  transform: translate(var(--fx-motion-x), var(--fx-motion-y)) scale(0.96);
  transition:
    opacity 110ms cubic-bezier(0.4, 0, 1, 1),
    transform 110ms cubic-bezier(0.4, 0, 1, 1),
    visibility 0s linear 110ms;
  will-change: opacity, transform;

  &[data-state="open"] {
    opacity: 1;
    visibility: visible;
    transform: none;
    transition:
      opacity 150ms cubic-bezier(0.16, 1, 0.3, 1),
      transform 220ms cubic-bezier(0.16, 1, 0.3, 1),
      visibility 0s;
  }

  /* Le glissement part du déclencheur, l'agrandissement aussi. */
  &[data-show-placement^="top"] {
    --fx-motion-y: var(--fx-motion-distance);
    --fx-motion-origin: bottom center;
  }
  &[data-show-placement^="left"] {
    --fx-motion-x: var(--fx-motion-distance);
    --fx-motion-y: 0px;
    --fx-motion-origin: center right;
  }
  &[data-show-placement^="right"] {
    --fx-motion-x: calc(var(--fx-motion-distance) * -1);
    --fx-motion-y: 0px;
    --fx-motion-origin: center left;
  }
  &[data-show-placement="bottom-start"] { --fx-motion-origin: top left; }
  &[data-show-placement="bottom-end"] { --fx-motion-origin: top right; }
  &[data-show-placement="top-start"] { --fx-motion-origin: bottom left; }
  &[data-show-placement="top-end"] { --fx-motion-origin: bottom right; }
  &[data-show-placement="left-start"] { --fx-motion-origin: top right; }
  &[data-show-placement="left-end"] { --fx-motion-origin: bottom right; }
  &[data-show-placement="right-start"] { --fx-motion-origin: top left; }
  &[data-show-placement="right-end"] { --fx-motion-origin: bottom left; }

  @media (prefers-reduced-motion: reduce) {
    transform: none;
  }
}

@utility u-fx-popper {
  @apply fixed left-(--fx-popper-placement-x) top-(--fx-popper-placement-y);
}

@utility animated-modal-content {
  animation: var(--un-modal-animation);
  /* Après le raccourci `animation`, qui la remettrait à none : la sortie garde son état final. */
  animation-fill-mode: both;
}

/* Animations du modal (modal.content : enter-animation / exit-animation).
   `none` en fin d'entrée, pas translateY(0) : un transform resté en place
   ferait du contenu le repère des éléments fixes (listbox, dropdown). */
@keyframes modal-animation-in {
  from {
    opacity: 0;
    transform: translateY(-1.5rem);
  }

  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes modal-animation-out {
